#include <stdlib.h>
#include <string.h>

/* sort the roster in place, highest score first */

struct player {
  char name[32];
  int score;
};

static int by_score(const void *a, const void *b) {
  const struct player *pa = a;
  const struct player *pb = b;
  return pb->score - pa->score;
}

void rank(struct player **roster, size_t n) {
  qsort(roster, n, sizeof(struct player *), by_score);
}

